from aerelith.core.result import Result

def merge_quota(a, b):
    if not a and not b:
        return Result(ok=False, value=None, err='E_EMPTY')

    merged = {}
    # Identify all unique keys across both dictionaries
    all_keys = set(a.keys()) | set(b.keys())

    for k in all_keys:
        if k in a and k in b:
            # If key is in both, only include it if values are identical
            if a[k] == b[k]:
                merged[k] = a[k]
        elif k in a:
            # Key only in a
            merged[k] = a[k]
        else:
            # Key only in b
            merged[k] = b[k]

    return Result(ok=True, value=merged, err=None)
