from aerelith.core.result import Result

def merge_quota(a, b):
    if not a and not b:
        return Result(ok=False, value=None, err='E_EMPTY')

    # Check for conflicts: if a key exists in both with different values
    for k in a:
        if k in b and a[k] != b[k]:
            return Result(ok=False, value=None, err='E_CONFLICT')

    merged = {}
    # Populate with all items from a
    for k, v in a.items():
        merged[k] = v

    # Populate with items from b that aren't already in merged
    for k, v in b.items():
        if k not in merged:
            merged[k] = v

    return Result(ok=True, value=merged, err=None)
