from aerelith.core.result import Result

def parse_window(spec):
    if not spec:
        return Result(ok=False, value=None, err='E_EMPTY')

    unit = spec[-1]
    num_str = spec[:-1]

    try:
        val = int(num_str)
        if val <= 0:
            return Result(ok=False, value=None, err='E_RANGE')
    except ValueError:
        return Result(ok=False, value=None, err='E_RANGE')

    multipliers = {'m': 1, 'h': 60, 'd': 1440}
    if unit not in multipliers:
        return Result(ok=False, value=None, err='E_RANGE')

    return Result(ok=True, value=val * multipliers[unit], err=None)
